mapper.select:
SELECT p.prod_id AS prodId, p.prod_name AS prodName, p.brand, p.client_id AS clientId, i.inventory_id AS inventoryId, i.ware_id AS wareId, i.quantity, i.last_inbound_date, i.last_outbound_date, wa.ware_name AS wareName, (SELECT CONCAT(w.warehouse_pos_x, w.warehouse_pos_y) FROM wareHouse w WHERE w.ware_id = i.ware_id LIMIT 1) AS warePosition FROM inventory i JOIN product p ON i.prod_id = p.prod_id JOIN category c ON p.prod_categoryid = c.prod_categoryid JOIN warehouse_area wa ON i.ware_id = wa.ware_id
AND c.category_level1 = #{category1}
AND c.category_level2 = #{category2}
AND c.category_level3 = #{category3}
AND p.prod_id LIKE CONCAT('%', #{keyword}, '%')
AND p.client_id LIKE CONCAT('%', #{keyword}, '%')
AND i.ware_id LIKE CONCAT('%', #{keyword}, '%')
ORDER BY i.quantity ASC
ORDER BY i.quantity DESC
ORDER BY p.prod_name ASC

SELECT DISTINCT category_level2
FROM category
WHERE category_level1 = #{category1}

SELECT DISTINCT category_level3
FROM category
WHERE category_level2 = #{category2}
